<script setup>
import { computed, ref } from 'vue';
import { Head, router, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
import { useConfirm } from '../../../Composables/useConfirm';

defineOptions({layout:AdminLayout});
const props=defineProps({reservation:{type:Object,required:true},tables:{type:Array,default:()=>[]},can:{type:Object,required:true},urls:{type:Object,required:true}});
const {ask}=useConfirm();
const cancellationReason=ref('');
const form=useForm({table_id:props.reservation.tableId??'',duration_minutes:props.reservation.durationMinutes,internal_notes:props.reservation.internalNotes??''});
const initials=computed(()=>(props.reservation.customer.name||'?').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join(''));
const selectedTable=computed(()=>props.tables.find(t=>String(t.id)===String(form.table_id)));
const activeAction=computed(()=>props.reservation.status==='pending'&&props.can.confirm?'confirm':props.reservation.status==='confirmed'&&props.can.seat?'seat':props.reservation.status==='seated'&&props.can.complete?'complete':null);
const actionLabels={confirm:{label:'تأكيد الحجز',icon:'bi-check-circle-fill',help:'تثبيت الموعد وتجهيزه للاستقبال'},seat:{label:'تسجيل وصول وجلوس',icon:'bi-people-fill',help:'ربط الضيوف بالطاولة وبدء الخدمة'},complete:{label:'إنهاء الحجز',icon:'bi-check2-all',help:'إغلاق الحجز بعد انتهاء الزيارة'}};
function save(){form.put(props.urls.update,{preserveScroll:true})}
async function runAction(action){const meta=actionLabels[action];const yes=await ask({title:`${meta.label}؟`,message:meta.help,confirmLabel:meta.label});if(yes)router.post(props.urls[action],action==='seat'?{table_id:form.table_id||null}:{},{preserveScroll:true})}
async function noShow(){const yes=await ask({title:'تسجيل عدم حضور؟',message:'سيُغلق الحجز كعدم حضور ولن يعود ضمن الحجوزات المنتظرة.',confirmLabel:'لم يحضر',danger:true});if(yes)router.post(props.urls.noShow,{}, {preserveScroll:true})}
async function cancel(){const yes=await ask({title:'إلغاء الحجز؟',message:cancellationReason.value||'سيُغلق الحجز ويُحفظ قرار الإلغاء في السجل.',confirmLabel:'إلغاء الحجز',danger:true});if(yes)router.post(props.urls.cancel,{cancelled_reason:cancellationReason.value||null},{preserveScroll:true})}
</script>
<template>
<Head :title="`حجز ${reservation.reference}`"/>
<PageHeader :title="`حجز ${reservation.reference}`" icon="bi-calendar2-check-fill" subtitle="الضيف والطاولة والخطوة التالية في شاشة واحدة" :crumbs="[{label:'الحجوزات',url:urls.index}]"/>
<div class="reservation-layout">
 <main>
  <section class="summary-card"><header><div><small>حالة الحجز</small><h2>{{reservation.statusLabel}}</h2></div><span class="state" :class="`is-${reservation.statusColor}`">{{reservation.statusLabel}}</span></header><div class="summary-grid"><div><i class="bi bi-calendar3"></i><span><small>الموعد</small><strong>{{reservation.reservedFor}}</strong></span></div><div><i class="bi bi-people"></i><span><small>الضيوف</small><strong>{{reservation.partySize}} أشخاص</strong></span></div><div><i class="bi bi-grid-3x3-gap"></i><span><small>الطاولة</small><strong>{{selectedTable?`طاولة ${selectedTable.number}`:'لم تُحدد بعد'}}</strong></span></div><div><i class="bi bi-clock"></i><span><small>المدة</small><strong>{{form.duration_minutes}} دقيقة</strong></span></div></div><div v-if="reservation.customerNotes" class="customer-note"><i class="bi bi-chat-quote"></i><div><small>طلب الضيف</small><p>{{reservation.customerNotes}}</p></div></div></section>
  <section v-if="can.update&&!reservation.isFinal" class="edit-card"><header><div><small>تجهيز الزيارة</small><h2>الطاولة وملاحظات الفريق</h2></div><i class="bi bi-pencil-square"></i></header><form @submit.prevent="save"><div class="fields"><label><span>الطاولة</span><select v-model="form.table_id" class="form-select"><option value="">تحديدها لاحقاً</option><option v-for="table in tables" :key="table.id" :value="table.id">طاولة {{table.number}} · {{table.capacity}} أشخاص{{table.status!=='available'&&table.id!==reservation.tableId?' · '+table.status:''}}</option></select><small v-if="form.errors.table_id" class="error">{{form.errors.table_id}}</small></label><label><span>مدة الحجز</span><select v-model="form.duration_minutes" class="form-select"><option v-for="minutes in [30,45,60,75,90,120,150,180]" :key="minutes" :value="minutes">{{minutes}} دقيقة</option></select><small v-if="form.errors.duration_minutes" class="error">{{form.errors.duration_minutes}}</small></label><label class="wide"><span>ملاحظات داخلية</span><textarea v-model="form.internal_notes" class="form-control" rows="3" maxlength="500" placeholder="مثال: يفضّل الطاولة الزاوية أو يحتاج كرسي أطفال"></textarea><small>يراها الفريق فقط، ولا تظهر للضيف.</small></label></div><footer><button class="btn btn-primary" :disabled="form.processing"><i class="bi bi-check2"></i> حفظ التجهيز</button></footer></form></section>
  <section v-if="reservation.confirmed||reservation.cancelled" class="history"><h2>سجل الحجز</h2><article v-if="reservation.confirmed"><i class="bi bi-check-circle"></i><span><strong>تم التأكيد</strong><small>{{reservation.confirmed.at}} · {{reservation.confirmed.by}}</small></span></article><article v-if="reservation.cancelled" class="cancelled"><i class="bi bi-x-circle"></i><span><strong>تم الإلغاء</strong><small>{{reservation.cancelled.at}} · {{reservation.cancelled.by}}</small><p v-if="reservation.cancelled.reason">{{reservation.cancelled.reason}}</p></span></article></section>
 </main>
 <aside>
  <section class="customer-card"><span class="avatar">{{initials}}</span><small>الضيف</small><h2>{{reservation.customer.name}}</h2><a v-if="reservation.customer.phone" :href="`tel:${reservation.customer.phone}`"><i class="bi bi-telephone"></i>{{reservation.customer.phone}}</a><a v-if="reservation.customer.email" :href="`mailto:${reservation.customer.email}`"><i class="bi bi-envelope"></i>{{reservation.customer.email}}</a></section>
  <section v-if="!reservation.isFinal" class="next-card"><small>الخطوة التالية</small><template v-if="activeAction"><i class="bi next-icon" :class="actionLabels[activeAction].icon"></i><h2>{{actionLabels[activeAction].label}}</h2><p>{{actionLabels[activeAction].help}}</p><button class="btn btn-primary" type="button" @click="runAction(activeAction)">{{actionLabels[activeAction].label}}</button></template><p v-else>لا يوجد إجراء متاح لصلاحيتك في هذه الحالة.</p><button v-if="reservation.status==='confirmed'&&can.noShow" type="button" class="secondary-action" @click="noShow"><i class="bi bi-person-x"></i> تسجيل عدم حضور</button></section>
  <section v-if="!reservation.isFinal&&can.cancel" class="cancel-card"><button type="button" @click="$event.currentTarget.parentElement.classList.toggle('open')"><span><i class="bi bi-x-circle"></i> إلغاء الحجز</span><i class="bi bi-chevron-down"></i></button><div><input v-model="cancellationReason" class="form-control" maxlength="255" placeholder="سبب الإلغاء (اختياري)"><button type="button" class="btn btn-outline-danger" @click="cancel">تأكيد الإلغاء</button></div></section>
 </aside>
</div>
</template>
<style scoped>
.reservation-layout{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:1rem;align-items:start}.reservation-layout main,.reservation-layout aside{display:grid;gap:.85rem}.summary-card,.edit-card,.history,.customer-card,.next-card,.cancel-card{background:#fff;border:1px solid #dce7e0;border-radius:16px;box-shadow:0 8px 28px rgba(20,60,39,.045)}.summary-card,.edit-card,.history{padding:1rem}.summary-card>header,.edit-card>header{display:flex;justify-content:space-between;align-items:center;padding-bottom:.8rem;border-bottom:1px solid #edf1ef}.summary-card h2,.summary-card small,.edit-card h2,.edit-card small{margin:0}.summary-card h2,.edit-card h2{font-size:1rem}.summary-card header small,.edit-card header small{font-size:.68rem;color:#829188}.state{padding:.35rem .65rem;border-radius:99px;font-size:.68rem;font-weight:850}.state.is-success{background:#e7f6ec;color:#0e743f}.state.is-warning{background:#fff5dd;color:#956313}.state.is-info{background:#e7f4fb;color:#197096}.state.is-danger,.state.is-dark{background:#fff0f0;color:#b33c3c}.state.is-secondary{background:#edf1ef;color:#5d6f65}.summary-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:.6rem;margin-top:.85rem}.summary-grid>div{display:flex;align-items:center;gap:.55rem;padding:.65rem;border:1px solid #e5ece8;border-radius:11px}.summary-grid i{color:#167343}.summary-grid span{display:grid}.summary-grid small{font-size:.64rem;color:#87948e}.summary-grid strong{font-size:.74rem}.customer-note{display:flex;gap:.6rem;margin-top:.75rem;padding:.75rem;border-radius:11px;background:#f7faf8;color:#526a5d}.customer-note small{font-size:.65rem;color:#829188}.customer-note p{margin:.1rem 0 0;font-size:.75rem}.fields{display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-top:.85rem}.fields label{display:grid;gap:.35rem}.fields .wide{grid-column:1/-1}.fields label>span{font-size:.73rem;font-weight:800}.fields label>small{font-size:.65rem;color:#7d8c84}.fields .error{color:#b93434}.edit-card footer{display:flex;justify-content:flex-end;margin-top:.75rem}.edit-card footer button{min-width:170px}.history h2{font-size:.85rem}.history article{display:flex;gap:.55rem;padding:.6rem 0;border-top:1px solid #edf1ef;color:#167343}.history article span{display:grid}.history article strong{font-size:.73rem}.history article small{font-size:.65rem;color:#7a8981}.history article p{font-size:.68rem;margin:.2rem 0 0;color:#734}.history .cancelled{color:#b43d3d}.customer-card,.next-card{padding:1rem;text-align:center}.avatar{width:58px;height:58px;border-radius:18px;background:#e7f5ec;color:#0f713f;display:grid;place-items:center;margin:0 auto .6rem;font-size:1.1rem;font-weight:900}.customer-card>small,.next-card>small{color:#829188;font-size:.67rem}.customer-card h2,.next-card h2{font-size:1rem;margin:.15rem 0 .65rem}.customer-card a{display:flex;justify-content:center;align-items:center;gap:.4rem;padding:.4rem;color:#486357;text-decoration:none;font-size:.72rem}.next-icon{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:#e8f5ed;color:#117140;margin:.7rem auto;font-size:1.2rem}.next-card p{color:#708078;font-size:.7rem;line-height:1.7}.next-card>.btn{width:100%;font-weight:850}.secondary-action{border:0;background:none;color:#5f7068;font-size:.7rem;margin-top:.7rem}.cancel-card{overflow:hidden}.cancel-card>button{width:100%;display:flex;justify-content:space-between;border:0;background:#fff;padding:.8rem 1rem;color:#a53c3c;font-size:.73rem;font-weight:800}.cancel-card>div{display:none;padding:0 1rem 1rem;gap:.5rem}.cancel-card.open>div{display:grid}.cancel-card.open>button .bi-chevron-down{transform:rotate(180deg)}@media(max-width:900px){.reservation-layout{grid-template-columns:1fr}.reservation-layout aside{grid-template-columns:1fr 1fr}.cancel-card{grid-column:1/-1}.summary-grid{grid-template-columns:1fr 1fr}}@media(max-width:600px){.reservation-layout aside,.fields,.summary-grid{grid-template-columns:1fr}.fields .wide{grid-column:auto}.summary-card,.edit-card,.history{padding:.85rem;border-radius:13px}.edit-card footer{position:sticky;bottom:0;background:#fff;padding-top:.6rem}.edit-card footer button{width:100%}}
</style>
